00095 template<typename T>
00096 struct AreaBuf : public Size
00097 {
00098   T*        buf;
00099   int       stride;
00100   // the proper type causes awful lot of errors
00101   //ptrdiff_t stride;
00102 
00103   AreaBuf()                                                                               : Size(),                  buf( NULL ), stride( 0 )          { }
00104   AreaBuf( T *_buf, const Size &size )                                                    : Size( size ),            buf( _buf ), stride( size.width ) { }
00105   AreaBuf( T *_buf, const int &_stride, const Size &size )                                : Size( size ),            buf( _buf ), stride( _stride )    { }
00106   AreaBuf( T *_buf, const SizeType &_width, const SizeType &_height )                     : Size( _width, _height ), buf( _buf ), stride( _width )     { }
00107   AreaBuf( T *_buf, const int &_stride, const SizeType &_width, const SizeType &_height ) : Size( _width, _height ), buf( _buf ), stride( _stride )    { }
00108 
00109   operator AreaBuf<const T>() const { return AreaBuf<const T>( buf, stride, width, height ); }
00110 
00111   void fill                 ( const T &val );
00112   void memset               ( const int val );
00113 
00114   void copyFrom             ( const AreaBuf<const T> &other );
00115   void roundToOutputBitdepth(const AreaBuf<const T> &src, const ClpRng& clpRng);
00116 
00117   void reconstruct          ( const AreaBuf<const T> &pred, const AreaBuf<const T> &resi, const ClpRng& clpRng);
00118   void copyClip             ( const AreaBuf<const T> &src, const ClpRng& clpRng);
00119 
00120   void subtract             ( const AreaBuf<const T> &other );
00121   void extendSingleBorderPel();
00122   void extendBorderPel      (  unsigned margin );
00123   void extendBorderPel(unsigned marginX, unsigned marginY);
00124   void padBorderPel         ( unsigned marginX, unsigned marginY, int dir );
00125   void addWeightedAvg       ( const AreaBuf<const T> &other1, const AreaBuf<const T> &other2, const ClpRng& clpRng, const int8_t bcwIdx);
00126   void removeWeightHighFreq ( const AreaBuf<T>& other, const bool bClip, const ClpRng& clpRng, const int8_t iBcwWeight);
00127   void addAvg               ( const AreaBuf<const T> &other1, const AreaBuf<const T> &other2, const ClpRng& clpRng );
00128   void removeHighFreq       ( const AreaBuf<T>& other, const bool bClip, const ClpRng& clpRng);
00129   void updateHistogram      ( std::vector<int32_t>& hist ) const;
00130 
00131   T    meanDiff             ( const AreaBuf<const T> &other ) const;
00132   void subtract             ( const T val );
00133 
00134   void linearTransform      ( const int scale, const int shift, const int offset, bool bClip, const ClpRng& clpRng );
00135 
00136   void transposedFrom       ( const AreaBuf<const T> &other );
00137 
00138   void toLast               ( const ClpRng& clpRng );
00139 
00140   void rspSignal            ( std::vector<Pel>& pLUT );
00141   void scaleSignal          ( const int scale, const bool dir , const ClpRng& clpRng);
00142   T    computeAvg           ( ) const;
00143 
00144         T& at( const int &x, const int &y )          { return buf[y * stride + x]; }
00145   const T& at( const int &x, const int &y ) const    { return buf[y * stride + x]; }
00146 
00147         T& at( const Position &pos )                 { return buf[pos.y * stride + pos.x]; }
00148   const T& at( const Position &pos ) const           { return buf[pos.y * stride + pos.x]; }
00149 
00150 
00151         T* bufAt( const int &x, const int &y )       { return &at( x, y ); }
00152   const T* bufAt( const int &x, const int &y ) const { return &at( x, y ); }
00153 
00154         T* bufAt( const Position& pos )              { return &at( pos ); }
00155   const T* bufAt( const Position& pos ) const        { return &at( pos ); }
00156 
00157   AreaBuf<      T> subBuf( const Position &pos, const Size &size )                                    { return AreaBuf<      T>( bufAt( pos  ), stride, size   ); }
00158   AreaBuf<const T> subBuf( const Position &pos, const Size &size )                              const { return AreaBuf<const T>( bufAt( pos  ), stride, size   ); }
00159   AreaBuf<      T> subBuf( const int &x, const int &y, const unsigned &_w, const unsigned &_h )       { return AreaBuf<      T>( bufAt( x, y ), stride, _w, _h ); }
00160   AreaBuf<const T> subBuf( const int &x, const int &y, const unsigned &_w, const unsigned &_h ) const { return AreaBuf<const T>( bufAt( x, y ), stride, _w, _h ); }
00161 };
