00178 #define SIZE_AWARE_PER_EL_OP( OP, INC )                     \
00179 if( ( width & 7 ) == 0 )                                    \
00180 {                                                           \
00181   for( int y = 0; y < height; y++ )                         \
00182   {                                                         \
00183     for( int x = 0; x < width; x += 8 )                     \
00184     {                                                       \
00185       OP( x + 0 );                                          \
00186       OP( x + 1 );                                          \
00187       OP( x + 2 );                                          \
00188       OP( x + 3 );                                          \
00189       OP( x + 4 );                                          \
00190       OP( x + 5 );                                          \
00191       OP( x + 6 );                                          \
00192       OP( x + 7 );                                          \
00193     }                                                       \
00194                                                             \
00195     INC;                                                    \
00196   }                                                         \
00197 }                                                           \
00198 else if( ( width & 3 ) == 0 )                               \
00199 {                                                           \
00200   for( int y = 0; y < height; y++ )                         \
00201   {                                                         \
00202     for( int x = 0; x < width; x += 4 )                     \
00203     {                                                       \
00204       OP( x + 0 );                                          \
00205       OP( x + 1 );                                          \
00206       OP( x + 2 );                                          \
00207       OP( x + 3 );                                          \
00208     }                                                       \
00209                                                             \
00210     INC;                                                    \
00211   }                                                         \
00212 }                                                           \
00213 else if( ( width & 1 ) == 0 )                               \
00214 {                                                           \
00215   for( int y = 0; y < height; y++ )                         \
00216   {                                                         \
00217     for( int x = 0; x < width; x += 2 )                     \
00218     {                                                       \
00219       OP( x + 0 );                                          \
00220       OP( x + 1 );                                          \
00221     }                                                       \
00222                                                             \
00223     INC;                                                    \
00224   }                                                         \
00225 }                                                           \
00226 else                                                        \
00227 {                                                           \
00228   for( int y = 0; y < height; y++ )                         \
00229   {                                                         \
00230     for( int x = 0; x < width; x++ )                        \
00231     {                                                       \
00232       OP( x );                                              \
00233     }                                                       \
00234                                                             \
00235     INC;                                                    \
00236   }                                                         \
00237 }
