00239 template<typename T>
00240 void AreaBuf<T>::fill(const T &val)
00241 {
00242   if( sizeof( T ) == 1 )
00243   {
00244     if( width == stride )
00245     {
00246       ::memset( buf, reinterpret_cast< const signed char& >( val ), width * height * sizeof( T ) );
00247     }
00248     else
00249     {
00250       T* dest = buf;
00251       size_t line = width * sizeof( T );
00252 
00253       for( unsigned y = 0; y < height; y++ )
00254       {
00255         ::memset( dest, reinterpret_cast< const signed char& >( val ), line );
00256 
00257         dest += stride;
00258       }
00259     }
00260   }
00261   else if( T( 0 ) == val )
00262   {
00263     if( width == stride )
00264     {
00265       ::memset( buf, 0, width * height * sizeof( T ) );
00266     }
00267     else
00268     {
00269       T* dest = buf;
00270       size_t line = width * sizeof( T );
00271 
00272       for( unsigned y = 0; y < height; y++ )
00273       {
00274         ::memset( dest, 0, line );
00275 
00276         dest += stride;
00277       }
00278     }
00279   }
00280   else
00281   {
00282     T* dest = buf;
00283 
00284 #define FILL_INC        dest      += stride
00285 #define FILL_OP( ADDR ) dest[ADDR] = val
00286 
00287     SIZE_AWARE_PER_EL_OP( FILL_OP, FILL_INC );
00288 
00289 #undef FILL_INC
00290 #undef FILL_OP
00291   }
00292 }
00293 
00294 template<typename T>
00295 void AreaBuf<T>::memset( const int val )
00296 {
00297   if( width == stride )
00298   {
00299     ::memset( buf, val, width * height * sizeof( T ) );
00300   }
00301   else
00302   {
00303     T* dest = buf;
00304     size_t line = width * sizeof( T );
00305 
00306     for( int y = 0; y < height; y++ )
00307     {
00308       ::memset( dest, val, line );
00309 
00310       dest += stride;
00311     }
00312   }
00313 }
