00315 template<typename T>
00316 void AreaBuf<T>::copyFrom( const AreaBuf<const T> &other )
00317 {
00318 #if !defined(__GNUC__) || __GNUC__ > 5
00319   static_assert( std::is_trivially_copyable<T>::value, "Type T is not trivially_copyable" );
00320 #endif
00321 
00322   CHECK( width  != other.width,  "Incompatible size" );
00323   CHECK( height != other.height, "Incompatible size" );
00324 
00325   if( buf == other.buf )
00326   {
00327     return;
00328   }
00329 
00330   if( width == stride && stride == other.stride )
00331   {
00332     memcpy( buf, other.buf, width * height * sizeof( T ) );
00333   }
00334   else
00335   {
00336           T* dst         = buf;
00337     const T* src         = other.buf;
00338     const unsigned srcStride = other.stride;
00339 
00340     for( unsigned y = 0; y < height; y++ )
00341     {
00342       memcpy( dst, src, width * sizeof( T ) );
00343 
00344       dst += stride;
00345       src += srcStride;
00346     }
00347   }
00348 }
00349 
00350 
00351 template<typename T>
00352 void AreaBuf<T>::subtract( const AreaBuf<const T> &other )
00353 {
00354   CHECK( width  != other.width,  "Incompatible size" );
00355   CHECK( height != other.height, "Incompatible size" );
00356 
00357         T* dest =       buf;
00358   const T* subs = other.buf;
00359 
00360 #define SUBS_INC        \
00361   dest +=       stride; \
00362   subs += other.stride; \
00363 
00364 #define SUBS_OP( ADDR ) dest[ADDR] -= subs[ADDR]
00365 
00366   SIZE_AWARE_PER_EL_OP( SUBS_OP, SUBS_INC );
00367 
00368 #undef SUBS_OP
00369 #undef SUBS_INC
00370 }
