00419 template<typename T>
00420 void AreaBuf<T>::removeWeightHighFreq(const AreaBuf<T>& other, const bool bClip, const ClpRng& clpRng, const int8_t bcwWeight)
00421 {
00422   const int8_t bcwWeightOther = g_BcwWeightBase - bcwWeight;
00423   const int8_t log2WeightBase = g_BcwLog2WeightBase;
00424 
00425   const Pel* src = other.buf;
00426   const int  srcStride = other.stride;
00427 
00428   Pel* dst = buf;
00429   const int  dstStride = stride;
00430 
00431 #if ENABLE_SIMD_OPT_BCW
00432   if(!bClip)
00433   {
00434     if(!(width & 7))
00435       g_pelBufOP.removeWeightHighFreq8(dst, dstStride, src, srcStride, width, height, 16, bcwWeight);
00436     else if(!(width & 3))
00437       g_pelBufOP.removeWeightHighFreq4(dst, dstStride, src, srcStride, width, height, 16, bcwWeight);
00438     else
00439       CHECK(true, "Not supported");
00440   }
00441   else
00442   {
00443 #endif
00444     Intermediate_Int normalizer = ((1 << 16) + (bcwWeight > 0 ? (bcwWeight >> 1) : -(bcwWeight >> 1))) / bcwWeight;
00445     Intermediate_Int weight0 = normalizer << log2WeightBase;
00446     Intermediate_Int weight1 = bcwWeightOther * normalizer;
00447 #define REM_HF_INC  \
00448   src += srcStride; \
00449   dst += dstStride; \
00450 
00451 #define REM_HF_OP_CLIP( ADDR ) dst[ADDR] = ClipPel<T>( T((dst[ADDR]*weight0 - src[ADDR]*weight1 + (1<<15))>>16), clpRng )
00452 #define REM_HF_OP( ADDR )      dst[ADDR] =             T((dst[ADDR]*weight0 - src[ADDR]*weight1 + (1<<15))>>16)
00453 
00454     if(bClip)
00455     {
00456       SIZE_AWARE_PER_EL_OP(REM_HF_OP_CLIP, REM_HF_INC);
00457     }
00458     else
00459     {
00460       SIZE_AWARE_PER_EL_OP(REM_HF_OP, REM_HF_INC);
00461     }
00462 
00463 #undef REM_HF_INC
00464 #undef REM_HF_OP
00465 #undef REM_HF_OP_CLIP
00466 #if ENABLE_SIMD_OPT_BCW
00467   }
00468 #endif
00469 }
00470 
00471 template<typename T>
00472 void AreaBuf<T>::removeHighFreq( const AreaBuf<T>& other, const bool bClip, const ClpRng& clpRng )
00473 {
00474   const T*  src       = other.buf;
00475   const int srcStride = other.stride;
00476 
00477         T*  dst       = buf;
00478   const int dstStride = stride;
00479 
00480 #if ENABLE_SIMD_OPT_BCW
00481   if (!bClip)
00482   {
00483     if(!(width & 7))
00484       g_pelBufOP.removeHighFreq8(dst, dstStride, src, srcStride, width, height);
00485     else if (!(width & 3))
00486       g_pelBufOP.removeHighFreq4(dst, dstStride, src, srcStride, width, height);
00487     else
00488       CHECK(true, "Not supported");
00489   }
00490   else
00491   {
00492 #endif
00493 
00494 #define REM_HF_INC  \
00495   src += srcStride; \
00496   dst += dstStride; \
00497 
00498 #define REM_HF_OP_CLIP( ADDR ) dst[ADDR] = ClipPel<T>( 2 * dst[ADDR] - src[ADDR], clpRng )
00499 #define REM_HF_OP( ADDR )      dst[ADDR] =             2 * dst[ADDR] - src[ADDR]
00500 
00501   if( bClip )
00502   {
00503     SIZE_AWARE_PER_EL_OP( REM_HF_OP_CLIP, REM_HF_INC );
00504   }
00505   else
00506   {
00507     SIZE_AWARE_PER_EL_OP( REM_HF_OP,      REM_HF_INC );
00508   }
00509 
00510 #undef REM_HF_INC
00511 #undef REM_HF_OP
00512 #undef REM_HF_OP_CLIP
00513 
00514 #if ENABLE_SIMD_OPT_BCW
00515   }
00516 #endif
00517 }
