00520 template<typename T>
00521 void AreaBuf<T>::updateHistogram( std::vector<int32_t>& hist ) const
00522 {
00523   const T* data = buf;
00524   for( std::size_t y = 0; y < height; y++, data += stride )
00525   {
00526     for( std::size_t x = 0; x < width; x++ )
00527     {
00528       hist[ data[x] ]++;
00529     }
00530   }
00531 }
00532 
00533 template<typename T>
00534 void AreaBuf<T>::extendBorderPel(unsigned marginX, unsigned marginY)
00535 {
00536   T* p = buf;
00537   int h = height;
00538   int w = width;
00539   int s = stride;
00540 
00541   CHECK((w + 2 * marginX) > s, "Size of buffer too small to extend");
00542   // do left and right margins
00543   for (int y = 0; y < h; y++)
00544   {
00545     for (int x = 0; x < marginX; x++)
00546     {
00547       *(p - marginX + x) = p[0];
00548       p[w + x] = p[w - 1];
00549     }
00550     p += s;
00551   }
00552 
00553   // p is now the (0,height) (bottom left of image within bigger picture
00554   p -= (s + marginX);
00555   // p is now the (-margin, height-1)
00556   for (int y = 0; y < marginY; y++)
00557   {
00558     ::memcpy(p + (y + 1) * s, p, sizeof(T) * (w + (marginX << 1)));
00559   }
00560 
00561   // p is still (-marginX, height-1)
00562   p -= ((h - 1) * s);
00563   // p is now (-marginX, 0)
00564   for (int y = 0; y < marginY; y++)
00565   {
00566     ::memcpy(p - (y + 1) * s, p, sizeof(T) * (w + (marginX << 1)));
00567   }
00568 }
00569 
00570 template<typename T>
00571 void AreaBuf<T>::padBorderPel( unsigned marginX, unsigned marginY, int dir )
00572 {
00573   T*  p = buf;
00574   int s = stride;
00575   int h = height;
00576   int w = width;
00577 
00578   CHECK( w  > s, "Size of buffer too small to extend" );
00579 
00580   // top-left margin
00581   if ( dir == 1 )
00582   {
00583     for( int y = 0; y < marginY; y++ )
00584     {
00585       for( int x = 0; x < marginX; x++ )
00586       {
00587         p[x] = p[marginX];
00588       }
00589       p += s;
00590     }
00591   }
00592 
00593   // bottom-right margin
00594   if ( dir == 2 )
00595   {
00596     p = buf + s * ( h - marginY ) + w - marginX;
00597 
00598     for( int y = 0; y < marginY; y++ )
00599     {
00600       for( int x = 0; x < marginX; x++ )
00601       {
00602         p[x] = p[-1];
00603       }
00604       p += s;
00605     }
00606   }
00607 }
00608 
00609 template<typename T>
00610 void AreaBuf<T>::extendBorderPel( unsigned margin )
00611 {
00612   T*  p = buf;
00613   int h = height;
00614   int w = width;
00615   int s = stride;
00616 
00617   CHECK( ( w + 2 * margin ) > s, "Size of buffer too small to extend" );
00618   // do left and right margins
00619   for( int y = 0; y < h; y++ )
00620   {
00621     for( int x = 0; x < margin; x++ )
00622     {
00623       *( p - margin + x ) = p[0];
00624       p[w + x] = p[w - 1];
00625     }
00626     p += s;
00627   }
00628 
00629   // p is now the (0,height) (bottom left of image within bigger picture
00630   p -= ( s + margin );
00631   // p is now the (-margin, height-1)
00632   for( int y = 0; y < margin; y++ )
00633   {
00634     ::memcpy( p + ( y + 1 ) * s, p, sizeof( T ) * ( w + ( margin << 1 ) ) );
00635   }
00636 
00637   // pi is still (-marginX, height-1)
00638   p -= ( ( h - 1 ) * s );
00639   // pi is now (-marginX, 0)
00640   for( int y = 0; y < margin; y++ )
00641   {
00642     ::memcpy( p - ( y + 1 ) * s, p, sizeof( T ) * ( w + ( margin << 1 ) ) );
00643   }
00644 }
00645 
00646 template<typename T>
00647 T AreaBuf<T>::meanDiff( const AreaBuf<const T> &other ) const
00648 {
00649   int64_t acc = 0;
00650 
00651   CHECK( width  != other.width,  "Incompatible size" );
00652   CHECK( height != other.height, "Incompatible size" );
00653 
00654   const T* src1 =       buf;
00655   const T* src2 = other.buf;
00656 
00657 #define MEAN_DIFF_INC   \
00658   src1 +=       stride; \
00659   src2 += other.stride; \
00660 
00661 #define MEAN_DIFF_OP(ADDR) acc += src1[ADDR] - src2[ADDR]
00662 
00663   SIZE_AWARE_PER_EL_OP( MEAN_DIFF_OP, MEAN_DIFF_INC );
00664 
00665 #undef MEAN_DIFF_INC
00666 #undef MEAN_DIFF_OP
00667 
00668   return T( acc / area() );
00669 }
00670 
00671 #if ENABLE_SIMD_OPT_BUFFER && defined(TARGET_SIMD_X86)
00672 template<> void AreaBuf<Pel>::subtract( const Pel val );
00673 #endif
00674 
00675 template<typename T>
00676 void AreaBuf<T>::subtract( const T val )
00677 {
00678   T* dst = buf;
00679 
00680 #define OFFSET_INC       dst       += stride
00681 #define OFFSET_OP(ADDR)  dst[ADDR] -= val
00682 
00683   SIZE_AWARE_PER_EL_OP( OFFSET_OP, OFFSET_INC );
00684 
00685 #undef OFFSET_INC
00686 #undef OFFSET_OP
00687 }
00688 
00689 template<typename T>
00690 void AreaBuf<T>::transposedFrom( const AreaBuf<const T> &other )
00691 {
00692   CHECK( width * height != other.width * other.height, "Incompatible size" );
00693 
00694         T* dst  =       buf;
00695   const T* src  = other.buf;
00696   width         = other.height;
00697   height        = other.width;
00698   stride        = stride < width ? width : stride;
00699 
00700   for( unsigned y = 0; y < other.height; y++ )
00701   {
00702     for( unsigned x = 0; x < other.width; x++ )
00703     {
00704       dst[y + x*stride] = src[x + y*other.stride];
00705     }
00706   }
00707 }
00708 
00709 template<typename T>
00710 T AreaBuf <T> ::computeAvg() const
00711 {
00712     const T* src = buf;
00713 #if ENABLE_QPA
00714     int64_t  acc = 0; // for picture-wise use in getGlaringColorQPOffset() and applyQPAdaptationChroma()
00715 #else
00716     int32_t  acc = 0;
00717 #endif
00718 #define AVG_INC      src += stride
00719 #define AVG_OP(ADDR) acc += src[ADDR]
00720     SIZE_AWARE_PER_EL_OP(AVG_OP, AVG_INC);
00721 #undef AVG_INC
00722 #undef AVG_OP
00723     return T ((acc + (area() >> 1)) / area());
00724 }
