00741 
00742   ChromaFormat chromaFormat;
00743   UnitBufBuffers bufs;
00744 
00745   UnitBuf() : chromaFormat( NUM_CHROMA_FORMAT ) { }
00746   UnitBuf( const ChromaFormat &_chromaFormat, const UnitBufBuffers&  _bufs ) : chromaFormat( _chromaFormat ), bufs( _bufs ) { }
00747   UnitBuf( const ChromaFormat &_chromaFormat,       UnitBufBuffers&& _bufs ) : chromaFormat( _chromaFormat ), bufs( std::forward<UnitBufBuffers>( _bufs ) ) { }
00748   UnitBuf( const ChromaFormat &_chromaFormat, const AreaBuf<T>  &blkY ) : chromaFormat( _chromaFormat ), bufs{ blkY } { }
00749   UnitBuf( const ChromaFormat &_chromaFormat,       AreaBuf<T> &&blkY ) : chromaFormat( _chromaFormat ), bufs{ std::forward<AreaBuf<T> >(blkY) } { }
00750   UnitBuf( const ChromaFormat &_chromaFormat, const AreaBuf<T>  &blkY, const AreaBuf<T>  &blkCb, const AreaBuf<T>  &blkCr ) : chromaFormat( _chromaFormat ), bufs{ blkY, blkCb, blkCr } { }
00751   UnitBuf( const ChromaFormat &_chromaFormat,       AreaBuf<T> &&blkY,       AreaBuf<T> &&blkCb,       AreaBuf<T> &&blkCr ) : chromaFormat( _chromaFormat ), bufs{ std::forward<AreaBuf<T> >(blkY), std::forward<AreaBuf<T> >(blkCb), std::forward<AreaBuf<T> >(blkCr) } { }
00752 
00753   operator UnitBuf<const T>() const
00754   {
00755     return UnitBuf<const T>( chromaFormat, ConstUnitBufBuffers( bufs.begin(), bufs.end() ) );
00756   }
00757 
00758         AreaBuf<T>& get( const ComponentID comp )        { return bufs[comp]; }
00759   const AreaBuf<T>& get( const ComponentID comp )  const { return bufs[comp]; }
00760 
00761         AreaBuf<T>& Y()        { return bufs[0]; }
00762   const AreaBuf<T>& Y()  const { return bufs[0]; }
00763         AreaBuf<T>& Cb()       { return bufs[1]; }
00764   const AreaBuf<T>& Cb() const { return bufs[1]; }
00765         AreaBuf<T>& Cr()       { return bufs[2]; }
00766   const AreaBuf<T>& Cr() const { return bufs[2]; }
