00768   void fill                 ( const T &val );
00769   void copyFrom             ( const UnitBuf<const T> &other, const bool lumaOnly = false, const bool chromaOnly = false );
00770   void roundToOutputBitdepth(const UnitBuf<const T> &src, const ClpRngs& clpRngs);
00771   void reconstruct          ( const UnitBuf<const T> &pred, const UnitBuf<const T> &resi, const ClpRngs& clpRngs );
00772   void copyClip             ( const UnitBuf<const T> &src, const ClpRngs& clpRngs, const bool lumaOnly = false, const bool chromaOnly = false );
00773   void subtract             ( const UnitBuf<const T> &other );
00774   void addWeightedAvg       ( const UnitBuf<const T> &other1, const UnitBuf<const T> &other2, const ClpRngs& clpRngs, const uint8_t bcwIdx = BCW_DEFAULT, const bool chromaOnly = false, const bool lumaOnly = false);
00775   void addAvg               ( const UnitBuf<const T> &other1, const UnitBuf<const T> &other2, const ClpRngs& clpRngs, const bool chromaOnly = false, const bool lumaOnly = false);
00776   void extendSingleBorderPel();
00777   void extendBorderPel(unsigned marginX, unsigned marginY);
00778   void padBorderPel         ( unsigned margin, int dir );
00779   void extendBorderPel      ( unsigned margin );
00780   void removeHighFreq       ( const UnitBuf<T>& other, const bool bClip, const ClpRngs& clpRngs
00781                             , const int8_t bcwWeight = g_BcwWeights[BCW_DEFAULT]
00782                             );
00783 
00784         UnitBuf<      T> subBuf (const UnitArea& subArea);
00785   const UnitBuf<const T> subBuf (const UnitArea& subArea) const;
00786   void colorSpaceConvert(const UnitBuf<T> &other, const bool forward, const ClpRng& clpRng);
00787 };
