00804 template<typename T>
00805 void UnitBuf<T>::copyFrom(const UnitBuf<const T> &other, const bool lumaOnly, const bool chromaOnly )
00806 {
00807   CHECK( chromaFormat != other.chromaFormat, "Incompatible formats" );
00808 
00809   CHECK( lumaOnly && chromaOnly, "Not allowed to have both lumaOnly and chromaOnly selected" );
00810   const size_t compStart = chromaOnly ? 1 : 0;
00811   const size_t compEnd   = lumaOnly ? 1 : (unsigned) bufs.size();
00812   for( size_t i = compStart; i < compEnd; i++ )
00813   {
00814     bufs[i].copyFrom( other.bufs[i] );
00815   }
00816 }
