00956 template<typename T>
00957 UnitBuf<T> UnitBuf<T>::subBuf( const UnitArea& subArea )
00958 {
00959   UnitBuf<T> subBuf;
00960   subBuf.chromaFormat = chromaFormat;
00961   unsigned blockIdx = 0;
00962 
00963   for( auto &subAreaBuf : bufs )
00964   {
00965     subBuf.bufs.push_back( subAreaBuf.subBuf( subArea.blocks[blockIdx].pos(), subArea.blocks[blockIdx].size() ) );
00966     blockIdx++;
00967   }
00968 
00969   return subBuf;
00970 }
